'use strict';
const el=s=>document.querySelector(s);let resourceLimit=8;
const resourceMapping={q:'#resource-query',audience:'#resource-audience',topic:'#resource-topic',type:'#resource-type',origin:'#resource-origin'};
function resourceState(){return Object.fromEntries(Object.entries(resourceMapping).map(([k,s])=>[k,el(s).value]));}
function resourceFiltered(){return LeadershipDiscovery.filter(TOOLKIT,resourceState());}
function renderResources(){const s=resourceState(),rows=resourceFiltered();el('#resource-count').textContent=`${rows.length} ${rows.length===1?'resource':'resources'} found${rows.length?' · Showing '+Math.min(resourceLimit,rows.length):''}`;el('#resource-audience-help').textContent=audienceHelp(s.audience,true);el('#resource-results').innerHTML=rows.slice(0,resourceLimit).map(r=>`<article class="resource-row" data-record="${escapeText(r.id)}"><div><div class="resource-meta"><span class="resource-type">${escapeText(r.type)}</span><span>${escapeText(r.origin)}</span><span class="resource-audience">${escapeText(r.audienceLabel)}</span></div><h3><a href="${escapeText(r.url)}" target="_blank" rel="noopener">${escapeText(r.title)}</a></h3><p>${escapeText(r.description)}</p><p class="resource-credit">${escapeText(r.owner)} <span aria-hidden="true">|</span> ${escapeText(r.topic)}</p></div><div class="resource-actions"><a class="text-link" href="${escapeText(r.url)}" target="_blank" rel="noopener">${r.type==='Video'?'Watch video':r.type==='Guide / job aid'?'Open guide':r.type==='Article'?'Read article':'Explore resources'}<span class="sr-only">: ${escapeText(r.title)}</span></a>${r.source!==r.url?`<a class="source-link" href="${escapeText(r.source)}" target="_blank" rel="noopener">${r.origin==='Other university'?'UF source collection':'HROE source collection'}</a>`:''}<span class="access">${r.type==='Guide / job aid'&&r.url.endsWith('.docx')?'Word document':r.type==='Guide / job aid'?'Published reference':r.type==='Learning collection'?'Linked learning may require sign-in':''}</span></div></article>`).join('')||'<div class="empty"><h3>Try another starting point.</h3><p>No resources match this combination. Remove a filter or try a broader phrase.</p><button class="button" type="button" data-empty-reset>Clear all filters</button></div>';el('#resource-more').hidden=rows.length<=resourceLimit;el('#resource-more').textContent='Show '+Math.min(8,Math.max(0,rows.length-resourceLimit))+' more '+(rows.length-resourceLimit===1?'resource':'resources');document.querySelectorAll('[data-topic]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.topic===s.topic)));renderFilterChips('#resource-active',[{key:'audience',value:s.audience!=='Employees',label:LeadershipDiscovery.labels[s.audience]},{key:'q',value:s.q,label:'Search: '+s.q},{key:'topic',value:s.topic,label:s.topic},{key:'type',value:s.type,label:s.type},{key:'origin',value:s.origin,label:s.origin}],key=>{el(resourceMapping[key]).value=key==='audience'?'Employees':'';resourceLimit=8;renderResources()});saveFilters(s);}
function resetResources(){for(const [k,id] of Object.entries(resourceMapping))el(id).value=k==='audience'?'Employees':'';resourceLimit=8;renderResources();}
document.querySelectorAll('.resource-filters input,.resource-filters select').forEach(e=>e.addEventListener(e.tagName==='INPUT'?'input':'change',()=>{resourceLimit=8;renderResources()}));document.querySelectorAll('[data-topic]').forEach(b=>b.addEventListener('click',()=>{el('#resource-topic').value=el('#resource-topic').value===b.dataset.topic?'':b.dataset.topic;resourceLimit=8;renderResources();el('#library').scrollIntoView();el('#resource-topic').focus({preventScroll:true})}));el('#resource-reset').addEventListener('click',resetResources);el('#resource-more').addEventListener('click',()=>{resourceLimit+=8;renderResources()});el('#resource-results').addEventListener('click',e=>{if(e.target.closest('[data-empty-reset]'))resetResources()});restoreFilters(resourceMapping);renderResources();
